    private val map: Map<String, LongArray> by lazy {
        DATA.split(';').associate { e ->
            val (id, cols) = e.split(':')
            id to cols.split(',').map { it.toLong(16) }.toLongArray()
        }
    }

    operator fun get(id: String): LongArray? = map[id]
